package sprint

import (
	"encoding/json"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func gauntletSprint(t *testing.T) (string, Sprint) {
	t.Helper()
	root := t.TempDir()
	sp := Sprint{Project: "alpha", Slug: "31-web", Path: filepath.Join(root, "projects", "alpha", "sprints", "31-web")}
	if err := os.MkdirAll(sp.Path, 0o755); err != nil {
		t.Fatal(err)
	}
	return root, sp
}

func gauntletLockPath(root string, sp Sprint) string {
	return filepath.Join(root, ".ultraplan", "locks", "sprint", sp.Project+"--"+sp.Slug+".lock")
}

func gauntletDeadPid(t *testing.T) int {
	t.Helper()
	cmd := exec.Command("true")
	if err := cmd.Run(); err != nil {
		t.Fatal(err)
	}
	return cmd.Process.Pid
}

func gauntletSeedDeadLock(root string, sp Sprint, pid int) error {
	path := gauntletLockPath(root, sp)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	data, _ := json.Marshal(verificationLockInfo{Project: sp.Project, Sprint: sp.Slug, PID: pid, AcquiredAt: time.Now().UTC().Add(-time.Hour)})
	return os.WriteFile(path, data, 0o644)
}

// Probe 1: a crash between O_EXCL create and content write leaves an empty or
// partial pidfile. Show that acquisition then fails closed forever.
func TestGauntletCorruptLockBricksAcquire(t *testing.T) {
	root, sp := gauntletSprint(t)
	for _, content := range []string{"", "{partial"} {
		if err := os.WriteFile(gauntletLockPath(root, sp), []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
		_, err := acquireVerificationFileLock(root, sp, time.Now())
		if !errors.Is(err, ErrVerificationConflict) {
			t.Fatalf("content=%q: err=%v, want ErrVerificationConflict", content, err)
		}
	}
	if _, err := acquireVerificationFileLock(root, sp, time.Now()); !errors.Is(err, ErrVerificationConflict) {
		t.Fatalf("expected permanent conflict, got %v", err)
	}
}

// Probe 2: project/slug join with "--" is ambiguous.
func TestGauntletLockFilenameCollision(t *testing.T) {
	root := t.TempDir()
	a := Sprint{Project: "a", Slug: "b--c"}
	b := Sprint{Project: "a--b", Slug: "c"}
	if pa, pb := gauntletLockPath(root, a), gauntletLockPath(root, b); pa != pb {
		t.Fatalf("expected collision, %s != %s", pa, pb)
	}
	lockA, err := acquireVerificationFileLock(root, a, time.Now())
	if err != nil {
		t.Fatalf("acquire a: %v", err)
	}
	defer lockA.release()
	if _, err := acquireVerificationFileLock(root, b, time.Now()); !errors.Is(err, ErrVerificationConflict) {
		t.Fatalf("unrelated sprint should conflict via colliding filename, got %v", err)
	}
}

// Probe 3: stale-lock steal race. Expected protocol: exactly one waiter steals
// the dead-owner lock; the bug is that an unconditional Remove after reading a
// dead snapshot can delete a LIVE lock created by a competing waiter, letting
// two waiters both hold the lease at once.
func TestGauntletLockStealDoubleAcquire(t *testing.T) {
	root, sp := gauntletSprint(t)
	dead := gauntletDeadPid(t)
	const workers = 16
	const iterations = 400
	var violations int64
	var live int32
	for i := 0; i < iterations; i++ {
		if err := gauntletSeedDeadLock(root, sp, dead); err != nil {
			t.Fatal(err)
		}
		start := make(chan struct{})
		var wg sync.WaitGroup
		for w := 0; w < workers; w++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				<-start
				lock, err := acquireVerificationFileLock(root, sp, time.Now())
				if err != nil {
					return // conflict: expected for losers
				}
				n := atomic.AddInt32(&live, 1)
				if n > 1 {
					atomic.AddInt64(&violations, 1)
				}
				time.Sleep(2 * time.Millisecond)
				atomic.AddInt32(&live, -1)
				_ = lock.release()
			}()
		}
		close(start)
		wg.Wait()
		if v := atomic.LoadInt64(&violations); v > 0 {
			break
		}
	}
	if v := atomic.LoadInt64(&violations); v > 0 {
		t.Fatalf("DOUBLE-ACQUIRE observed in %d iteration(s): concurrent live leases on one sprint", v)
	}
	t.Log("no double-acquire observed (window not hit)")
}
EOF
